contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint v) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        uint callerBefore = address(this).balance;
        uint cBefore = address(c).balance;
        require(address(this).balance >= v, "insufficient test balance");

        bool reverted;
        c.withdraw(v); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint callerAfter = address(this).balance;
        uint cAfter = address(c).balance;

        assert(
            (reverted && callerAfter == callerBefore && cAfter == cBefore) ||
            (!reverted && callerAfter == callerBefore + v && cAfter + v == cBefore)
        );
    }

    receive() external payable {}
}

