// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 v) internal {
        vm.deal(address(c), VALUE_CAP);
        uint callerBefore = address(this).balance;
        uint cBefore = address(c).balance;
        vm.assume(address(this).balance >= v);
        bool reverted;
        try c.withdraw(v) { reverted = false; } catch { reverted = true; }
        uint callerAfter = address(this).balance;
        uint cAfter = address(c).balance;
        assertTrue((reverted && callerAfter == callerBefore && cAfter == cBefore) ||
            (!reverted && callerAfter == callerBefore + v && cAfter + v == cBefore));
    }

    function testFuzz_run(uint256 v) public {
        _run(v);
    }

    receive() external payable {}
}
